/**
 * Hand-checked ratings for ingredient rows that the CosIng pass and the alias linker couldn't rate:
 * label spellings, Indian and Ayurvedic ingredients, brand-name complexes, and text that isn't an
 * ingredient at all. Used by rate-ingredients-by-hand.ts.
 *
 * Rules, same as everywhere else in SkinLens:
 * - "avoid" only for a confirmed EU ban or a drug that doesn't belong in a cosmetic.
 * - When we can't tell what a name means ("Color", "Herbal Extracts"), it stays unrated: we never
 *   guess a rating.
 * - Descriptions are our own wording: short, plain, not alarmist.
 */

type Zone = 'green' | 'yellow' | 'red';
export type HandRating = { zone: Zone; text: string; fragrance?: boolean; paraben?: boolean; sulfate?: boolean };

const g = (text: string, extra: Partial<HandRating> = {}): HandRating => ({ zone: 'green', text, ...extra });
const y = (text: string, extra: Partial<HandRating> = {}): HandRating => ({ zone: 'yellow', text, ...extra });
const r = (text: string): HandRating => ({ zone: 'red', text });

// Shared descriptions.
const OIL = g('Plant oil. Softens skin and hair and helps hold in moisture.');
const BUTTER = g('Plant butter. A rich moisturiser that softens and protects dry skin.');
const PLANT = g('Plant extract, added mainly for its antioxidants and soothing properties. Not known to cause problems at the amounts used in skincare.');
const FRUIT = g('Fruit extract, mostly there for antioxidants. Gentle for most skin.');
const AYURVEDIC = g('Traditional Ayurvedic herb. At the amounts used in skincare it is not known to cause problems, though any plant can trigger allergy in a few people.');
const SEAWEED = g('Seaweed extract. Helps skin hold moisture. Gentle.');
const MUSHROOM = g('Mushroom extract, used for its antioxidants. Gentle; the anti-ageing claims are mostly marketing.');
const STEM_CELLS = g('Plant "stem cell" extract: a lab-grown plant cell culture used as an antioxidant. Gentle; the anti-ageing claims are mostly marketing.');
const FERMENT = g('Probiotic ferment: a filtrate from food fermented with friendly bacteria. Used to soothe and support the skin barrier. Gentle.');
const ESSENTIAL = y('Essential oil, added for scent. Like fragrance, it can irritate or cause allergy, especially on sensitive skin.', { fragrance: true });
const CITRUS_OILS = y('Citrus essential oils. Add scent, but can irritate and may make skin react to sunlight; better in wash-off products than in leave-on ones worn in the sun.', { fragrance: true });
const COLOUR = g('Colour additive allowed in cosmetics in the EU and US.');
const EMOLLIENT = g('Emollient. Softens skin and gives the formula a smooth feel. Not known to cause problems.');
const EMULSIFIER = g('Emulsifier. Keeps oil and water mixed. Not known to cause problems at the amounts used.');
const THICKENER = g('Thickener. Gives the product its texture. Not known to cause problems.');
const POLYMER = g('Polymer that thickens the formula or forms a light film. Not absorbed into skin and not known to cause problems.');
const SILICONE = g('Silicone. Makes the product glide and leaves a smooth, silky finish. Not known to cause problems.');
const CONDITIONER = g('Conditioning agent. Smooths hair and reduces frizz and static.');
const MILD_CLEANSER = g('Gentle cleansing agent, used in mild shampoos and face washes.');
const HARSH_CLEANSER = y('Strong cleansing agent. Cleans well but can leave skin or scalp dry and tight, especially on sensitive skin.', { sulfate: true });
const PEPTIDE = g('Peptide: a short chain of amino acids used in anti-ageing products to support firmness. Gentle; evidence for big results is limited.');
const CERAMIDE = g('Plant ceramide: a lipid like the ones your skin barrier is made of. Helps skin hold moisture. Gentle.');
const HUMECTANT = g('Humectant. Draws water into the skin to keep it hydrated. Gentle.');
const PROTEIN = g('Protein that coats hair or skin to make it feel smoother and stronger. Gentle.');
const NUCLEOSIDE = g('Nucleoside (a DNA building block), used in some anti-ageing and lash serums. Little evidence either way; not known to cause problems.');
const MINERAL = g('Mineral used to absorb oil, add slip or bulk up a powder. Not known to cause problems.');
const SALT = g('Mineral salt, used as a scrub or bath salt or to thicken a formula. Fine for most skin, but it stings on cuts.');
const PH = g('Adjusts pH so the product stays gentle and stable. Used in small amounts.');
const CHELATOR = g('Chelating agent. Binds minerals in water so the product stays stable. Used in tiny amounts.');
const SOLVENT = g('Solvent or carrier. Helps dissolve other ingredients. Not known to cause problems.');
const PARABEN_GROUP = y('A group of preservatives, but the label doesn\'t say which ones. Methyl- and ethylparaben are well studied and allowed; some others are restricted or banned in the EU.', { paraben: true });
const PARTIAL_POLYMER = g('Part of a longer polymer name, cut off on the label. The polymers it can belong to thicken the formula and are not known to cause problems.');

